question:
What will be the output of the following code?

int main() {
    int x = 5;
    printf("%d", x++);
    return 0;
}

What is the output of the following code?

int x = 5, y = 10;
printf("%d", x > y ? x : y);

What will be the output of the following code?

int a = 5;
int *p = &a;
printf("%d", *p);

What will the following code print?

int main() {
    char str[] = "Hello";
    printf("%c", str[1]);
    return 0;
}
